def inside_out(x: str) -> str:
    def transform(word):
        if len(word) <= 2:
            return word[::-1]
        mid = len(word) // 2
        if len(word) % 2 == 0:
            return word[0] + word[-1] + word[-2:1:-1] + word[1]
        else:
            return word[0] + word[-1] + word[-3:mid:-1] + word[mid] + word[mid+1:-2][::-1] + word[1]
    return ' '.join(transform(word) for word in x.split())
